let input = $json.body ?? $json;
if (typeof input === 'string') { try { input = JSON.parse(input); } catch { throw new Error('Request body must be valid JSON.'); } }
const scenePrompt = typeof input.prompt === 'string' ? input.prompt.trim() : '';
if (scenePrompt.length < 20 || scenePrompt.length > 2500) throw new Error('Send a scene prompt between 20 and 2,500 characters.');
const styleGuide = 'Make one 16:9 still in the supplied reference images’ visual language. Reference 1 is the casual recurring character; reference 2 defines the room and background drawing style. Use flat 2D educational cartoon art, bold slightly irregular black ink outlines, simple expressive faces, clear silhouettes, solid colors, minimal restrained shading, yellow or cream walls, green furniture, blue accents, and warm amber or brown details. Use one frozen action and one clear focal point. No text, captions, labels, lettering, logos, watermarks, borders, photorealism, 3D, anime, or thin corporate vector art.';
const prompt = styleGuide + '\n\nSCENE TO ILLUSTRATE:\n' + scenePrompt;
const references = [{fileId:'1B8FZJvtx2udKt-WHK_WlLF5RmWCl6hE4',role:'casual_character',name:'normal man.png'},{fileId:'19_rZZhpt3du495njrjnO5nuPWQjxnMAQ',role:'background_style',name:'yellow living room.png'}];
return references.map((reference, referenceIndex) => ({json:{...reference,referenceIndex,prompt}}));

const files = $input.all();
const referenceRecords = $('Prepare Image Request').all().map(item => item.json);
if (files.length !== 2 || referenceRecords.length !== 2) throw new Error('Exactly two approved style references are required.');
const inputReferences = [];
for (let index = 0; index < files.length; index++) {
  const binary = files[index].binary?.data;
  if (!binary) throw new Error('A Google Drive reference did not download as an image.');
  const buffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  const mimeType = binary.mimeType || 'image/png';
  if (!mimeType.startsWith('image/')) throw new Error('A style reference is not an image file.');
  inputReferences.push({type:'image_url',image_url:{url:'data:'+mimeType+';base64,'+buffer.toString('base64')}});
}
const prompt = referenceRecords[0].prompt;
return [{json:{model:'openai/gpt-image-2.5-flare',prompt,n:1,aspect_ratio:'16:9',quality:'low',input_references:inputReferences}}];

const response = $json ?? {};
const body = response.body && typeof response.body === 'object' ? response.body : response;
const image = body.data?.[0];
const b64 = image?.b64_json;
if (!b64) {
  const providerError = body.error;
  const errorMessage = typeof providerError === 'string' ? providerError : providerError?.message || response.error?.message || body.message || 'OpenRouter did not return image bytes.';
  const statusCode = Number(response.statusCode || providerError?.code || 502);
  return [{json:{ok:false,statusCode,error:String(errorMessage).slice(0,1200),model:'openai/gpt-image-2.5-flare'}}];
}
const mimeType = image.media_type || body.media_type || 'image/jpeg';
if (!mimeType.startsWith('image/')) throw new Error('The provider returned an unsupported media type.');
const buffer = Buffer.from(b64,'base64');
const extension = mimeType === 'image/png' ? 'png' : 'jpg';
const binary = await this.helpers.prepareBinaryData(buffer,'fred-scene.'+extension,mimeType);
return [{json:{ok:true,model:'openai/gpt-image-2.5-flare',mimeType,costUsd:body.usage?.cost ?? null,imageData:'data:'+mimeType+';base64,'+b64},binary:{data:binary}}];
